#!/usr/bin/env python3
"""Build the standalone, first-pass style listening/review page."""
from __future__ import annotations

import argparse
import html
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
CONFIG = ROOT / "config" / "nino-style-review-v1.json"
MANIFEST = ROOT / "outputs" / "dataset" / "style-review-v1" / "manifest.json"
OUTPUT = ROOT / "outputs" / "dataset" / "style-review-v1" / "review.html"


def safe_json(value: object) -> str:
    # Prevent manifest strings from terminating the script element.
    return json.dumps(value, ensure_ascii=False).replace("<", "\\u003c").replace(">", "\\u003e").replace("&", "\\u0026")


def asset_url(path: str, clip_id: str, kind: str) -> str:
    # Server routes are stable across project layouts. file:// uses paths from this page.
    return f"/audio/{kind}/{html.escape(clip_id, quote=True)}.wav" if kind in ("clip", "context") else path


